\label{res:ashikhmin}
A linear code over $\mathbb{F}_{q}$ is minimal if
\begin{equation}
\frac{w_{\max}}{w_{\min}} < \frac{q}{q-1},
\end{equation}
where $w_{\max}$ and $w_{\min}$ denote the maximum and minimum non-zero Hamming weights in $\mathcal{C}$.

\label{thm:diam-girth}
Let $p$ be an odd prime. The zero-divisor graph $\Gamma(R)$ satisfies:
\begin{enumerate}
    \item[(i)] $\operatorname{diam}(\Gamma(R)) = 2$,
    \item[(ii)] $\operatorname{girth}(\Gamma(R)) = 3$.
\end{enumerate}

\label{parameters_code_adjmatrix}
Let $A(\Gamma(R))$ be the adjacency matrix of the zero-divisor graph $\Gamma(R)$ of the ring $R$. Then following statements hold:                                                                                       
\begin{enumerate}
    \item The linear code $\mathcal{C}_{\mathbb{F}_{p}}(A(\Gamma(R)))$ generated by the rows of $A(\Gamma(R))$ over $\mathbb{F}_{p}$ is a
    $[p^{3}-1,\, p^{2},\, 2]_{p}$
    linear code.
   \item The dual code $\mathcal{C}_{\mathbb{F}_{p}}(A(\Gamma(R)))^{\perp}$ is a
$[p^{3}-1,\, p^{3}-p^{2}-1,\, 2]_{p}$  linear code consisting precisely of all vectors supported on $V_{1}=S_{u}\cup S_{u+u^{2}}\cup S_{u+u^{3}}\cup S_{u+u^{2}+u^{3}}$ whose components sum to zero modulo $p$.
\end{enumerate}

\label{parameters_code_Laplacianmatrix}
Let $L(\Gamma(R))$ be the Laplacian matrix of the zero-divisor graph $\Gamma(R)$.
\begin{enumerate}
    \item The linear code $\mathcal{C}_{\mathbb{F}_{p}}(L(\Gamma(R)))$ generated by the rows of $L(\Gamma(R))$ over $\mathbb{F}_{p}$ is a $[p^{3}-1,\, p^{3}-2,\, 2]_{p}$  linear code.
    \item Its dual code $\mathcal{C}_{\mathbb{F}_{p}}(L(\Gamma(R)))^{\perp}$ is a
    $[p^{3}-1,\, 1,\, p^{3}-1]_{p}$ repetition code spanned by the all-ones vector $\mathbf{1}_{p^{3}-1}$.
\end{enumerate}

\label{thm:weight-enum-laplacian}
Let $\mathcal{C}_{\mathbb{F}_p}(L(\Gamma(R)))$ be the $[p^3-1, p^3-2, 2]_p$ linear code generated over $\mathbb{F}_p$ by the rows of $L(\Gamma(R))$. Then the polynomial weight enumerator of $\mathcal{C}_{\mathbb{F}_p}(L(\Gamma(R)))$ is given by 
\begin{equation*}
W_{\mathcal{C}}(z) = \frac{1}{p}\left[ \left(1 + (p-1)z\right)^{p^3-1} + (p-1)(1 - z)^{p^3-1} \right],
\end{equation*}
and for each $w \in \{0, 1, \dots, p^3-1\}$, the exact number of codewords of Hamming weight $w$ is 
\begin{equation*}
A_w = \frac{1}{p} \binom{p^3-1}{w} \left[ (p-1)^w + (p-1)(-1)^w \right].
\end{equation*}

\label{cor:laplacian-lcd}
Let $p \ge 3$ be an odd prime.
\begin{enumerate}
    \item The Laplacian code $\mathcal{C}_{\mathbb{F}_p}(L(\Gamma(R)))$ of length $n = p^3 - 1$ is strictly an LCD code over $\mathbb{F}_p$.
    \item For the induced complete bipartite subgraph $\Gamma_{\mathrm{bip}} = \Gamma[V_1, V_3]$, the Laplacian code $\mathcal{C}_{\mathbb{F}_p}(L(\Gamma_{\mathrm{bip}}))$ is an LCD code over $\mathbb{F}_p$.
\end{enumerate}

Let $\mathcal{C}_{\mathbb{F}_p}(A(\Gamma(R)))$ and $\mathcal{C}_{\mathbb{F}_p}(L(\Gamma(R)))$ be the linear codes generated by the adjacency and Laplacian matrices of $\Gamma(R)$. Then following statements hold:
\begin{enumerate}
    \item $\operatorname{Aut}(\Gamma(R)) \le \operatorname{PAut}(\mathcal{C}_{\mathbb{F}_p}(A(\Gamma(R))))$;
    \item $\operatorname{PAut}(\mathcal{C}_{\mathbb{F}_p}(L(\Gamma(R)))) \cong S_{p^3-1}$.
\end{enumerate}

\label{lem:subspace-intersection}
Let $R = \mathbb{F}_p[x]/\langle x^4 \rangle$ and let $D_{V_1} = uR \setminus u^2 R$ be the maximal independent defining set of $\Gamma(R)$. Identifying $D_{V_1}$ with its coordinate projections in $\mathbb{F}_p^3$ across the basis $\{u, u^2, u^3\}$, the intersection of $D_{V_1}$ with any $1$-dimensional subspace $W \subset \mathbb{F}_p^3$ satisfies:
\[
|D_{V_1} \cap W| = 
\begin{cases}
0, & \text{if } W \subseteq \{0\} \times \mathbb{F}_p^2, \\
p - 1, & \text{if } W \not\subseteq \{0\} \times \mathbb{F}_p^2.
\end{cases}
\]
In particular, $\max_{\dim(W)=1} |D_{V_1} \cap W| = p - 1$.

Let $W = \operatorname{span}_{\mathbb{F}_p}\{(b_1, b_2, b_3)\}$ be a $1$-dimensional subspace in $\mathbb{F}_p^3$ generated by a non-zero vector $(b_1, b_2, b_3)$. Any point $v \in W$ is of the form $\lambda (b_1, b_2, b_3)$ for some scalar $\lambda \in \mathbb{F}_p$. By definition of $D_{V_1}$, an element belongs to $D_{V_1}$ if and only if its leading coefficient is non-zero, which requires $\lambda b_1 \in \mathbb{F}_p^*$.
\begin{itemize}
    \item If $b_1 = 0$: then $\lambda b_1 = 0$ for all $\lambda \in \mathbb{F}_p$. Thus, no non-zero vector in $W$ belongs to $D_{V_1}$, giving $|D_{V_1} \cap W| = 0$.
    \item If $b_1 \ne 0$: then $\lambda b_1 \in \mathbb{F}_p^*$ holds for all $p - 1$ choices of $\lambda \in \mathbb{F}_p^*$. Consequently, all non-zero points along the line $W$ lie in $D_{V_1}$, yielding $|D_{V_1} \cap W| = p - 1$.
\end{itemize}
Therefore, $\max_{\dim(W)=1} |D_{V_1} \cap W| = p - 1$, with equality attained if and only if $b_1 \ne 0$.
